#include <map>
#include <string>
#include <vector>

// Assuming the existence of a Memcache client library with the following functions:
// - memcached_stat(): retrieves statistics from a Memcache server
// - memcached_stat_free(): frees the allocated statistics memory
// - memcached_server_list(): returns a list of Memcache servers

std::map<std::string, std::map<std::string, std::string>> get_memcache_extended_stats(const std::string& type = "", int slabid = 0, int limit = 100) {
    std::map<std::string, std::map<std::string, std::string>> result;

    // Retrieve statistics from the Memcache server
    memcached_st* stats = memcached_stat();
    if (!stats) {
        return result; // Return empty map if retrieval fails
    }

    try {
        // Get the list of servers
        memcached_server_st* servers = memcached_server_list(stats);
        size_t server_count = memcached_server_count(stats);

        // Limit the number of servers to process
        size_t servers_to_process = std::min(static_cast<size_t>(server_count), static_cast<size_t>(limit));

        // Iterate through each server
        for (size_t i = 0; i < servers_to_process; ++i) {
            memcached_server_st* server = memcached_server_get(stats, i);
            if (!server) {
                continue; // Skip invalid server entries
            }

            // Construct a unique key for this server
            std::string server_key = server->hostname + ":" + std::to_string(server->port);

            // Get statistics for this server
            std::map<std::string, std::string> server_stats;
            if (type.empty()) {
                // Get all statistics
                for (size_t j = 0; j < server->stat_count; ++j) {
                    memcached_stat_st* stat = memcached_stat_get(stats, j);
                    if (!stat) {
                        continue;
                    }
                    server_stats[stat->key] = stat->value;
                }
            } else {
                // Get statistics of a specific type
                for (size_t j = 0; j < server->stat_count; ++j) {
                    memcached_stat_st* stat = memcached_stat_get(stats, j);
                    if (!stat) {
                        continue;
                    }
                    if (stat->type == type) {
                        server_stats[stat->key] = stat->value;
                    }
                }
            }

            // Filter by slab ID if provided
            if (slabid > 0) {
                std::map<std::string, std::string> filtered_stats;
                for (const auto& [key, value] : server_stats) {
                    if (key.find("slab_" + std::to_string(slabid)) != std::string::npos) {
                        filtered_stats[key] = value;
                    }
                }
                server_stats = filtered_stats;
            }

            // Add the server statistics to the result
            if (!server_stats.empty()) {
                result[server_key] = server_stats;
            }
        }

        // Free the allocated statistics memory
        memcached_stat_free(stats);
    } catch (...) {
        // In case of any exception, ensure we free the allocated memory
        memcached_stat_free(stats);
        throw;
    }

    return result;
}
